#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// Card structure
typedef struct {
    int suit;  // 0,1,2,3
    int rank;  // 2-14 (11=J,12=Q,13=K,14=A)
    int points; // basic points from suit
} Card;

// Hand rankings
enum {
    HIGH_CARD = 0,
    ONE_PAIR,
    TWO_PAIR,
    THREE_OF_A_KIND,
    STRAIGHT,
    FLUSH,
    FULL_HOUSE,
    FOUR_OF_A_KIND,
    STRAIGHT_FLUSH,
    ROYAL_FLUSH
};

// Multipliers for each ranking
const int multipliers[] = {1, 2, 3, 5, 8, 10, 15, 20, 50, 100};

// Compare function for sorting cards by rank
int cmp_card(const void *a, const void *b) {
    Card *ca = (Card *)a;
    Card *cb = (Card *)b;
    return ca->rank - cb->rank;
}

// Evaluate hand ranking
int evaluate_hand(Card hand[5]) {
    // Sort by rank
    qsort(hand, 5, sizeof(Card), cmp_card);

    int ranks[5], suits[5];
    for (int i = 0; i < 5; i++) {
        ranks[i] = hand[i].rank;
        suits[i] = hand[i].suit;
    }

    // Check flush
    int is_flush = 1;
    for (int i = 1; i < 5; i++) {
        if (suits[i] != suits[0]) {
            is_flush = 0;
            break;
        }
    }

    // Check straight
    int is_straight = 1;
    // Special case: A,2,3,4,5 (wheel)
    if (ranks[0] == 2 && ranks[1] == 3 && ranks[2] == 4 && ranks[3] == 5 && ranks[4] == 14) {
        is_straight = 1;
    } else {
        for (int i = 1; i < 5; i++) {
            if (ranks[i] != ranks[i-1] + 1) {
                is_straight = 0;
                break;
            }
        }
    }

    // Count rank frequencies
    int freq[15] = {0};
    for (int i = 0; i < 5; i++) {
        freq[ranks[i]]++;
    }

    int pairs = 0, threes = 0, fours = 0;
    for (int i = 2; i <= 14; i++) {
        if (freq[i] == 2) pairs++;
        else if (freq[i] == 3) threes++;
        else if (freq[i] == 4) fours++;
    }

    // Determine ranking
    if (is_flush && is_straight) {
        if (ranks[4] == 14 && ranks[0] == 10) return ROYAL_FLUSH;
        return STRAIGHT_FLUSH;
    }
    if (fours == 1) return FOUR_OF_A_KIND;
    if (threes == 1 && pairs == 1) return FULL_HOUSE;
    if (is_flush) return FLUSH;
    if (is_straight) return STRAIGHT;
    if (threes == 1) return THREE_OF_A_KIND;
    if (pairs == 2) return TWO_PAIR;
    if (pairs == 1) return ONE_PAIR;
    return HIGH_CARD;
}

