// Card representation
struct Card {
    int rank; // 1-13 (A=1, J=11, Q=12, K=13)
    int suit; // 0-3 (0=Spades, 1=Hearts, 2=Diamonds, 3=Clubs)
    int points; // basic points from suit
};

// Hand rankings
enum HandRank {
    HIGH_CARD = 0,
    ONE_PAIR = 1,
    TWO_PAIR = 2,
    THREE_OF_A_KIND = 3,
    STRAIGHT = 4,
    FLUSH = 5,
    FULL_HOUSE = 6,
    FOUR_OF_A_KIND = 7,
    STRAIGHT_FLUSH = 8
};

// Multipliers for each hand rank
const int multiplier[] = {1, 2, 4, 6, 8, 10, 12, 16, 20};

// Convert rank character to number
int rankToNum(char c) {
    if (c >= '2' && c <= '9') return c - '0';
    if (c == 'A') return 1;
    if (c == 'T') return 10;
    if (c == 'J') return 11;
    if (c == 'Q') return 12;
    if (c == 'K') return 13;
    return 0; // should not happen
}

// Convert suit character to number and points
pair<int,int> suitToNum(char c) {
    if (c == 'S') return {0, 4};
    if (c == 'H') return {1, 3};
    if (c == 'D') return {2, 2};
    if (c == 'C') return {3, 1};
    return {0,0}; // should not happen
}

// Check if hand is a straight (ace can be low or high)
bool isStraight(vector<int>& ranks) {
    vector<int> r = ranks;
    sort(r.begin(), r.end());
    // Check normal straight
    bool straight = true;
    for (int i = 0; i < 4; i++) {
        if (r[i+1] - r[i] != 1) {
            straight = false;
            break;
        }
    }
    if (straight) return true;
    // Check A-2-3-4-5 (ace as low)
    if (r[0] == 1 && r[1] == 2 && r[2] == 3 && r[3] == 4 && r[4] == 13) return true;
    return false;
}

// Evaluate hand rank
HandRank evaluateHand(vector<Card>& hand) {
    vector<int> ranks;
    vector<int> suits;
    for (auto& c : hand) {
        ranks.push_back(c.rank);
        suits.push_back(c.suit);
    }

    // Count rank frequencies
    map<int,int> freq;
    for (int r : ranks) freq[r]++;

    vector<int> counts;
    for (auto& p : freq) counts.push_back(p.second);
    sort(counts.begin(), counts.end(), greater<int>());

    bool flush = true;
    for (int i = 1; i < 5; i++) {
        if (suits[i] != suits[0]) {
            flush = false;
            break;
        }
    }

    bool straight = isStraight(ranks);

    if (flush && straight) return STRAIGHT_FLUSH;
    if (counts.size() == 2 && counts[0] == 4) return FOUR_OF_A_KIND;
    if (counts.size() == 2 && counts[0] == 3 && counts[1] == 2) return FULL_HOUSE;
    if (flush) return FLUSH;
    if (straight) return STRAIGHT;
    if (counts[0] == 3) return THREE_OF_A_KIND;
    if (counts.size() == 3 && counts[0] == 2 && counts[1] == 2) return TWO_PAIR;
    if (counts[0] == 2) return ONE_PAIR;
    return HIGH_CARD;
}

