public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = br.readLine()) != null && !line.isEmpty()) {
            // Parse input: 5 cards, each like "AH" "2D" etc.
            String[] cards = line.trim().split("\\s+");
            if (cards.length != 5) continue;

            // Extract ranks and suits
            char[] ranks = new char[5];
            char[] suits = new char[5];
            for (int i = 0; i < 5; i++) {
                String c = cards[i];
                ranks[i] = c.charAt(0);
                suits[i] = c.charAt(1);
            }

            // Compute basic points sum
            int basicSum = 0;
            for (char r : ranks) {
                basicSum += basicPoint(r);
            }

            // Compute hand rank multiplier
            int multiplier = getMultiplier(ranks, suits);

            // Output result
            System.out.println(basicSum * multiplier);
        }
    }

    static int basicPoint(char rank) {
        switch (rank) {
            case 'A': return 1;
            case '2': return 2;
            case '3': return 3;
            case '4': return 4;
            case '5': return 5;
            case '6': return 6;
            case '7': return 7;
            case '8': return 8;
            case '9': return 9;
            case 'T': return 10;
            case 'J': return 11;
            case 'Q': return 12;
            case 'K': return 13;
            default: return 0;
        }
    }

    static int getMultiplier(char[] ranks, char[] suits) {
        // Convert ranks to numeric values for easier comparison
        int[] vals = new int[5];
        for (int i = 0; i < 5; i++) {
            vals[i] = rankToValue(ranks[i]);
        }
        Arrays.sort(vals);

        boolean flush = true;
        for (int i = 1; i < 5; i++) {
            if (suits[i] != suits[0]) {
                flush = false;
                break;
            }
        }

        boolean straight = true;
        // Check normal straight
        for (int i = 1; i < 5; i++) {
            if (vals[i] != vals[i-1] + 1) {
                straight = false;
                break;
            }
        }
        // Special case A-2-3-4-5 (wheel)
        if (!straight && vals[0] == 2 && vals[1] == 3 && vals[2] == 4 && vals[3] == 5 && vals[4] == 14) {
            straight = true;
            // For wheel, treat A as 1 for straight detection, but values already sorted with A=14
            // We'll handle it by checking pattern
        }

        // Count frequencies
        int[] freq = new int[15]; // indices 2..14
        for (int v : vals) {
            freq[v]++;
        }

        boolean fourKind = false;
        boolean threeKind = false;
        int pairCount = 0;
        for (int i = 2; i <= 14; i++) {
            if (freq[i] == 4) fourKind = true;
            else if (freq[i] == 3) threeKind = true;
            else if (freq[i] == 2) pairCount++;
        }

        // Determine hand rank and multiplier
        if (straight && flush) {
            // Royal flush or straight flush
            if (vals[4] == 14 && vals[0] == 10) {
                return 250; // Royal flush
            } else {
                return 50; // Straight flush
            }
        } else if (fourKind) {
            return 25; // Four of a kind
        } else if (threeKind && pairCount == 1) {
            return 15; // Full house
        } else if (flush) {
            return 10; // Flush
        } else if (straight) {
            return 8; // Straight
        } else if (threeKind) {
            return 5; // Three of a kind
        } else if (pairCount == 2) {
            return 3; // Two pair
        } else if (pairCount == 1) {
            return 2; // One pair
        } else {
            return 1; // High card
        }
    }

    static int rankToValue(char rank) {
        switch (rank) {
            case 'A': return 14;
            case 'K': return 13;
            case 'Q': return 12;
            case 'J': return 11;
            case 'T': return 10;
            default: return rank - '0';
        }
    }
}

