            int[] ranks = new int[5];
            int[] suits = new int[5];
            int totalPoints = 0;

            String suitChars = "SHDC";
            for (int i = 0; i < 5; i++) {
                String card = parts[i];
                char suitChar = card.charAt(card.length()-1);
                int suitIdx = suitChars.indexOf(suitChar);
                suits[i] = suitIdx;
                totalPoints += suitPoints[suitIdx];
                String rankStr = card.substring(0, card.length()-1);
                if (rankStr.equals("A")) ranks[i] = 14;
                else if (rankStr.equals("K")) ranks[i] = 13;
                else if (rankStr.equals("Q")) ranks[i] = 12;
                else if (rankStr.equals("J")) ranks[i] = 11;
                else ranks[i] = Integer.parseInt(rankStr);
            }

            int multiplier = getMultiplier(ranks, suits);
            System.out.println(totalPoints * multiplier);
        }
    }

    static int getMultiplier(int[] ranks, int[] suits) {
        Arrays.sort(ranks);
        boolean flush = suits[0]==suits[1] && suits[1]==suits[2] && suits[2]==suits[3] && suits[3]==suits[4];
        boolean straight = (ranks[4]-ranks[0]==4 && countDistinct(ranks)==5);
        // A-2-3-4-5
        boolean wheelStraight = ranks[0]==2&&ranks[1]==3&&ranks[2]==4&&ranks[3]==5&&ranks[4]==14;
        if (wheelStraight) straight = true;

        Map<Integer,Integer> freq = new HashMap<>();
        for (int r : ranks) freq.merge(r, 1, Integer::sum);
        List<Integer> counts = new ArrayList<>(freq.values());
        Collections.sort(counts, Collections.reverseOrder());

        if (flush && straight) {
            if (ranks[0]==10||wheelStraight&&false) return 100; // royal
            boolean royal = ranks[0]==10&&ranks[4]==14;
            return royal ? 100 : 50;
        }
        if (counts.get(0)==4) return 20;
        if (counts.get(0)==3 && counts.get(1)==2) return 10;
        if (flush) return 7;
        if (straight) return 5;
        if (counts.get(0)==3) return 4;
        if (counts.get(0)==2 && counts.get(1)==2) return 3;
        if (counts.get(0)==2) return 2;
        return 1;
    }

    static int countDistinct(int[] a) {
        Set<Integer> s = new HashSet<>();
        for (int x : a) s.add(x);
        return s.size();
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        // Basic points for suits: S, H, D, C
        int s = fs.nextInt();
