            int rank;
            if (numStr.equals("A")) rank = 14;
            else if (numStr.equals("K")) rank = 13;
            else if (numStr.equals("Q")) rank = 12;
            else if (numStr.equals("J")) rank = 11;
            else rank = Integer.parseInt(numStr);

            rankCount[rank]++;
        }

        boolean flush = true;
        for (int i = 1; i < 5; i++) {
            if (suits[i] != suits[0]) {
                flush = false;
                break;
            }
        }

        boolean straight = false;
        int distinct = 0;
        int minRank = 15, maxRank = 0;
        for (int r = 2; r <= 14; r++) {
            if (rankCount[r] > 0) {
                distinct++;
                minRank = Math.min(minRank, r);
                maxRank = Math.max(maxRank, r);
            }
        }
        if (distinct == 5 && maxRank - minRank == 4) straight = true;
        // A,2,3,4,5
        if (rankCount[14] == 1 && rankCount[2] == 1 && rankCount[3] == 1 && rankCount[4] == 1 && rankCount[5] == 1) {
            straight = true;
        }

        int maxSame = 0;
        int pairCount = 0;
        boolean three = false;
        boolean four = false;
        for (int r = 2; r <= 14; r++) {
            maxSame = Math.max(maxSame, rankCount[r]);
            if (rankCount[r] == 4) four = true;
            if (rankCount[r] == 3) three = true;
            if (rankCount[r] == 2) pairCount++;
        }

        int multiplier;
        if (straight && flush) multiplier = 100;
        else if (four) multiplier = 50;
        else if (three && pairCount == 1) multiplier = 10;
        else if (flush) multiplier = 7;
        else if (straight) multiplier = 5;
        else if (three) multiplier = 4;
        else if (pairCount == 2) multiplier = 3;
        else if (pairCount == 1) multiplier = 2;
        else multiplier = 1;

        System.out.println((long) basicSum * multiplier);
    }

    static int suitPoint(char suit, int s, int h, int d, int c) {
        switch (suit) {
            case 'S': return s;
            case 'H': return h;
            case 'D': return d;
            case 'C': return c;
        }
        return 0;
    }
}

